SELECT CASE WHEN p.price >= 960 THEN 'high' WHEN p.price >= 470 THEN 'mid' ELSE 'low' END AS price_bucket, AVG(oi.quantity) AS avg_quantity, COUNT(*) AS num_order_items FROM order_items oi INNER JOIN products p ON oi.product_id = p.id INNER JOIN suppliers s ON p.supplier_id = s.id GROUP BY CASE WHEN p.price >= 960 THEN 'high' WHEN p.price >= 470 THEN 'mid' ELSE 'low' END ORDER BY price_bucket ASC;
